async function validate(body, user) {
  const kind = body.kind;
  if (!['story', 'event', 'spotlight'].includes(kind)) throw new HttpError(400, 'Tipo inválido.');
  if (kind !== 'story' && user.role !== 'admin') throw new HttpError(403, 'Só a curadoria pode publicar este conteúdo.');
  const title = text(body.title, {
    max: 120,
    required: true,
    label: 'Título'
  });
  const intro = text(body.intro, {
    max: 1600,
    label: 'Introdução'
  });
  const data = body.payload || {};
  let payload;
  if (kind === 'story') {
    if (!Array.isArray(data.frames) || data.frames.length < 5 || data.frames.length > 10) throw new HttpError(400, 'Escolhe entre 5 e 10 fotografias.');
    const seen = new Set();
    payload = {
      frames: await Promise.all(data.frames.map(async frame => {
        if (!frame || !Number.isSafeInteger(Number(frame.photoId))) throw new HttpError(400, 'Fotografia inválida.');
        const photo = await db.prepare("SELECT user_id FROM photos WHERE id = ? AND status = 'approved'").get(Number(frame.photoId));
        if (!photo || photo.user_id !== user.id && user.role !== 'admin' || seen.has(Number(frame.photoId))) throw new HttpError(400, 'Usa fotografias próprias, aprovadas e sem repetições.');
        seen.add(Number(frame.photoId));
        return {
          photoId: Number(frame.photoId),
          caption: text(frame.caption, {
            max: 400,
            label: 'Legenda'
          })
        };
      }))
    };
  } else if (kind === 'event') {
    const date = new Date(data.date);
    const capacity = Number(data.capacity);
    if (!Number.isFinite(date.getTime()) || !Number.isSafeInteger(capacity) || capacity < 1 || capacity > 500) throw new HttpError(400, 'Data ou limite de participantes inválido.');
    payload = {
      date: date.toISOString(),
      capacity,
      location: text(data.location, {
        max: 200,
        required: true,
        label: 'Ponto de encontro'
      })
    };
  } else {
    const username = text(data.username, {
      max: 30,
      required: true
    });
    if (!(await db.prepare('SELECT id FROM users WHERE username = ?').get(username))) throw new HttpError(400, 'Fotógrafo não encontrado.');
    payload = {
      username
    };
  }
  return {
    kind,
    title,
    intro,
    payload
  };
}
router.post('/items', requireUser, async (req, res) => {
  const item = await validate(req.body, req.user);
  const status = req.user.role === 'admin' ? 'published' : 'pending';
  const {
    lastInsertRowid
  } = await db.prepare('INSERT INTO community_items (kind,user_id,title,intro,payload,status) VALUES (?,?,?,?,?,?)').run(item.kind, req.user.id, item.title, item.intro, JSON.stringify(item.payload), status);
  res.status(201).json({
    item: await shape(await getItem(lastInsertRowid), req.user)
  });
});
router.patch('/items/:id', requireAdmin, async (req, res) => {
  const old = await getItem(req.params.id);
  if (!old || old.kind === 'challenge') throw new HttpError(404, 'Conteúdo não encontrado.');
  const status = req.body.status ?? old.status;
  if (!['pending', 'published', 'archived'].includes(status)) throw new HttpError(400, 'Estado inválido.');
  if (req.body.kind && req.body.kind !== old.kind) throw new HttpError(400, 'O tipo de conteúdo não pode ser alterado.');
  const value = status === 'archived' && Object.keys(req.body).length === 1 ? {
    title: old.title,
    intro: old.intro,
    payload: JSON.parse(old.payload)
  } : await validate({
    ...old,
    payload: JSON.parse(old.payload),
    ...req.body
  }, req.user);
  await db.prepare('UPDATE community_items SET title = ?, intro = ?, payload = ?, status = ? WHERE id = ?').run(value.title, value.intro, JSON.stringify(value.payload), status, old.id);
  res.json({
    item: await shape(await getItem(old.id), req.user)
  });
});
router.post('/items/:id/participate', requireUser, async (req, res) => {
  const item = await getItem(req.params.id);
  if (!item || item.kind === 'challenge' || item.status !== 'published') throw new HttpError(404, 'Conteúdo não encontrado.');
  const payload = JSON.parse(item.payload);
  if (item.kind === 'event') {
    await tx(async () => {
      if (new Date(payload.date) <= new Date()) throw new HttpError(409, 'Este encontro já terminou.');
      if (!(await db.prepare('SELECT 1 FROM event_rsvps WHERE item_id = ? AND user_id = ?').get(item.id, req.user.id))) {
        if ((await db.prepare('SELECT COUNT(*) AS n FROM event_rsvps WHERE item_id = ?').get(item.id)).n >= payload.capacity) throw new HttpError(409, 'As vagas estão preenchidas.');
        await db.prepare('INSERT INTO event_rsvps VALUES (?,?)').run(item.id, req.user.id);
      }
    });
  } else throw new HttpError(400, 'Conteúdo sem inscrições.');
  res.json({
    item: await shape(await getItem(item.id), req.user)
  });
});
